#nullable enable // autogenerated

using MVZ2Logic.Models;
using PVZEngine.Tools.Unity;
using UnityEngine;
using UnityEngine.Rendering;

namespace MVZ2.Models
{
    public class ModelContainer : MonoBehaviour
    {
        public void SetModel(IModelBuilder builder)
        {
            RemoveModel();

            var parent = modelRoot;
            if (!parent.Exists())
            {
                parent = transform;
            }
            model = builder.Build(parent);
        }
        public void RemoveModel()
        {
            if (model.Exists())
            {
                Destroy(model.gameObject);
                model = null;
            }
        }
        public void SetSortingLayerName(string layer)
        {
            if (sortingGroup.Exists())
            {
                sortingGroup.sortingLayerName = layer;
            }
        }
        public void SetSortingOrder(int order)
        {
            if (sortingGroup.Exists())
            {
                sortingGroup.sortingOrder = order;
            }
        }
        public Model? model;
        public SortingGroup? sortingGroup;
        public Transform? modelRoot;
    }
}
